create database customer_behavior_analysis;
use customer_behavior_analysis;
-- 1. Revenue Analysis
-- compared total revenue generated by male and female customers
SELECT 
    gender,
    SUM(purchase_amount) AS revenue
FROM customer_behavior_clean_dataset
GROUP BY gender;

-- 2. Disscount and Spending Analysis
-- Identified disscount users whos purchase amount were at or above the overall  everage
select customer_id , purchase_amount from customer_behavior_clean_dataset
where discount_applied='yes'
and purchase_amount>= (select avg (purchase_amount) from customer_behavior_clean_dataset);

-- 3. Product Rating Analysis
-- Ranked the top 5 products by avg review rating 
SELECT
    item_purchased,
    ROUND(AVG(review_rating), 2) AS average_review_rating
FROM customer_behavior_clean_dataset
GROUP BY item_purchased
ORDER BY average_review_rating DESC
LIMIT 5;

-- 4. Shoping Analysis
-- Compared avg purchase amount for standard and express shiping
SELECT
    shipping_type,
    ROUND(AVG(purchase_amount), 2) AS avg_purchase_amount
FROM customer_behavior_clean_dataset
WHERE shipping_type IN ('standard', 'express')
GROUP BY shipping_type;

-- 5. Subscription Analysis
-- compared customer count , avg spending and total revenue between subscribers and non-subscribers 
select subscription_status,
count(customer_id) as total_customers,
round(avg(purchase_amount),2) as avg_spending,
round(sum(purchase_amount),2) as total_revenue
from customer_behavior_clean_dataset
group by subscription_status
order by avg_spending , total_revenue desc;

-- 6. Discount dependancy analysis
-- identified top 10 products by percentage of purchaes with discount applied
SELECT 
    item_purchased,
    ROUND(
        100 * SUM(
            CASE 
                WHEN discount_applied = 'yes' THEN 1
                ELSE 0
            END
        ) / COUNT(*), 2
    ) AS discount_rate
FROM customer_behavior_clean_dataset
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;

-- 7. Customer segment
-- classified customers into new , returning and loyal segments based in previous purchase
with customer_type as 
(select customer_id,previous_purchases,
case when previous_purchases=1 then 'new'
when previous_purchases between 2 and 10 then 'returning'
else 'loyal'
end as customer_segment
from customer_behavior_clean_dataset)
select customer_segment,
count(*) as number_of_customers
from customer_type
group by customer_segment;

-- 8. Product Popularity Analysis — Identified the top 3 most purchased products within each category.
WITH item_counts AS (
    SELECT category,
           item_purchased,
           COUNT(customer_id) AS total_orders,
           ROW_NUMBER() OVER (PARTITION BY category ORDER BY COUNT(customer_id) DESC) AS item_rank
    FROM customer_behavior_clean_dataset
    GROUP BY category, item_purchased
)
SELECT item_rank,category, item_purchased, total_orders
FROM item_counts
WHERE item_rank <=3;


-- 9. Repeat Buyer Analysis — Compared subscription status among customers with more than 5 previous purchases.
SELECT subscription_status,
       COUNT(customer_id) AS repeat_buyers
FROM customer_behavior_clean_dataset
WHERE previous_purchases > 5
GROUP BY subscription_status;


-- 10. Age Group Revenue Analysis — Compared total revenue across customer age groups.
SELECT 
    age_group,
    SUM(purchase_amount) AS total_revenue
FROM customer_behavior_clean_dataset
GROUP BY age_group
ORDER BY total_revenue desc;